PREFIX t: <https://xgap.test/toy/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT (SUM(?amount) AS ?total) WHERE { ?n a t:Person . OPTIONAL { ?n t:amount ?amount } }

SELECT DISTINCT ?eligible WHERE { {
SELECT DISTINCT ?source ?target ?n0 WHERE {
  { ?n0 ?_p0 ?_o0 . }
  UNION
  { ?_s0 ?_p1 ?n0 . }
  ?n0 <https://xgap.test/toy/age> ?v0 .
  FILTER(?v0 >= 30)
  BIND(?n0 AS ?source)
  BIND(?n0 AS ?target)
}
} ?source <https://xgap.test/toy/id> ?eligible . }

PREFIX t: <https://xgap.test/toy/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT (SUM(COALESCE(?amount,0)) AS ?total) WHERE { ?n a t:Person . OPTIONAL { ?n t:amount ?amount } }

PREFIX t: <https://xgap.test/toy/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT (SUM(COALESCE(?credit,0)) AS ?total) WHERE { ?n a t:Person . OPTIONAL { ?n t:credit ?credit } }

PREFIX t: <https://xgap.test/toy/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT (COUNT(*) AS ?people) (COUNT(?score) AS ?present) (COUNT(DISTINCT ?canonical) AS ?unique) WHERE { ?n a t:Person . OPTIONAL { ?n t:score ?score } BIND(IF(isNumeric(?score),xsd:integer(FLOOR(xsd:decimal(?score))),?score) AS ?canonical) }

PREFIX t: <https://xgap.test/toy/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?low ?high WHERE { { SELECT (xsd:integer(FLOOR(?s)) AS ?low) WHERE { ?n a t:Person ; t:score ?s . FILTER(isNumeric(?s)) } ORDER BY ?s LIMIT 1 } { SELECT ?high WHERE { ?n a t:Person ; t:score ?high . FILTER(DATATYPE(?high)=xsd:boolean) } ORDER BY DESC(?high) LIMIT 1 } }

PREFIX t: <https://xgap.test/toy/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT (SUM(COALESCE(?amount,0)) AS ?total) (COUNT(*) AS ?n) WHERE { ?person a t:Person ; t:score ?score . FILTER(isNumeric(?score) && ?score=1) OPTIONAL { ?person t:amount ?amount } }

PREFIX t: <https://xgap.test/toy/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT (STR(?a) AS ?left) (STR(?b) AS ?right) WHERE { ?a a t:Person ; t:score ?x . ?b a t:Person ; t:score ?y . FILTER(COALESCE((isNumeric(?x) && isNumeric(?y) && ?x=?y) || (DATATYPE(?x)=DATATYPE(?y) && ?x=?y),false)) }

PREFIX t: <https://xgap.test/toy/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT DISTINCT ?score WHERE { ?n a t:Person . OPTIONAL { ?n t:score ?raw } BIND(IF(isNumeric(?raw),xsd:integer(FLOOR(xsd:decimal(?raw))),?raw) AS ?score) }

PREFIX t: <https://xgap.test/toy/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT (SUM(DISTINCT ?value) AS ?total) WHERE { ?n a t:Person ; t:score ?raw . FILTER(isNumeric(?raw) && ?raw>0) BIND(xsd:double(xsd:integer(FLOOR(xsd:decimal(?raw)))) AS ?value) }

PREFIX t: <https://xgap.test/toy/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT (COUNT(*) AS ?rows) (COUNT(?v) AS ?present) (SUM(COALESCE(?v,0)) AS ?total) (MIN(?v) AS ?low) (MAX(?v) AS ?high) WHERE { ?n a t:Person . FILTER(?n=t:missing) OPTIONAL { ?n t:amount ?v } }

PREFIX t: <https://xgap.test/toy/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT (SUM(COALESCE(?credit,0)) AS ?total) WHERE { t:a a t:Person ; t:credit ?credit }

PREFIX t: <https://xgap.test/toy/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT (COUNT(*) AS ?rows) (COUNT(?v) AS ?present) (SUM(COALESCE(?v,0)) AS ?total) (MIN(?v) AS ?low) (MAX(?v) AS ?high) WHERE { ?n a t:Person . OPTIONAL { ?n t:vacant ?v } }
